import numpy as np
import time

def run_packing() -> tuple[np.ndarray, np.ndarray, float]:
    '''
    Construct a packing of 26 circles in the unit square.

    Returns:
        centers: numpy array of shape (26, 2)
        radii: numpy array of shape (26,)
        sum_radii: objective value (sum of radii)
    '''
    # Walls: 0=left (x=0), 1=right (x=1), 2=bottom (y=0), 3=top (y=1)
    # We use coordinate transforms so that a chosen wall maps to u=0 (and u=r),
    # and optionally a perpendicular wall maps to v=0 (and v=r).
    # This allows a unified treatment for candidate construction.
    eps = 1e-10
    tol = 1e-9
    max_circles = 26
    start_time = time.time()
    time_limit = 580.0  # seconds, keep margin

    centers = []  # list of (x,y)
    radii = []    # list of r

    def wall_transform_single(wall, x, y):
        # Map (x,y) to (u,v) with wall at u=0
        if wall == 0:   # left x=0
            return x, y
        elif wall == 1: # right x=1
            return 1.0 - x, y
        elif wall == 2: # bottom y=0
            return y, x
        elif wall == 3: # top y=1
            return 1.0 - y, x
        else:
            raise ValueError("Invalid wall")

    def wall_inverse_single(wall, u, v):
        # Map (u,v) back to (x,y)
        if wall == 0:
            return u, v
        elif wall == 1:
            return 1.0 - u, v
        elif wall == 2:
            return v, u
        elif wall == 3:
            return v, 1.0 - u
        else:
            raise ValueError("Invalid wall")

    def wall_transform_pair(vwall, hwall, x, y):
        # Map (x,y) to (u,v) where vwall (vertical) => u=0, hwall (horizontal) => v=0
        # vwall in {0,1}, hwall in {2,3}
        if vwall == 0:
            u = x
        else:
            u = 1.0 - x
        if hwall == 2:
            v = y
        else:
            v = 1.0 - y
        return u, v

    def wall_inverse_pair(vwall, hwall, u, v):
        if vwall == 0:
            x = u
        else:
            x = 1.0 - u
        if hwall == 2:
            y = v
        else:
            y = 1.0 - v
        return x, y

    def circles_uv_for_single_wall(wall):
        # Return arrays of (u_i, v_i, r_i) for existing circles under single-wall transform
        if not centers:
            return np.zeros((0,3))
        arr = []
        for (x, y), r in zip(centers, radii):
            u, v = wall_transform_single(wall, x, y)
            arr.append((u, v, r))
        return np.array(arr)

    def circles_uv_for_pair(vwall, hwall):
        if not centers:
            return np.zeros((0,3))
        arr = []
        for (x, y), r in zip(centers, radii):
            u, v = wall_transform_pair(vwall, hwall, x, y)
            arr.append((u, v, r))
        return np.array(arr)

    def feasible(x, y, r, allow_tangent=True):
        # Check bounds
        if not (r >= -tol):
            return False
        if not (x - r >= -tol and x + r <= 1.0 + tol and y - r >= -tol and y + r <= 1.0 + tol):
            return False
        # Check non-overlap
        for (cx, cy), cr in zip(centers, radii):
            d = np.hypot(cx - x, cy - y)
            if allow_tangent:
                if d < cr + r - 1e-8:
                    return False
            else:
                if d <= cr + r - 1e-8:
                    return False
        return True

    def add_circle(x, y, r):
        centers.append((float(x), float(y)))
        radii.append(float(r))

    def dedup_candidate(cands, new_cand):
        # Avoid near-duplicate centers/radii in candidates
        x, y, r = new_cand
        for (cx, cy, cr) in cands:
            if abs(cr - r) < 1e-9 and (abs(cx - x) + abs(cy - y)) < 1e-9:
                return True
        return False

    def corner_only_candidate(vwall, hwall):
        # Max circle tangent to two perpendicular walls at a corner and no overlap with existing circles.
        # In (u,v) coordinates, center=(r,r), constraints from circles give quadratic roots; r_max is min of larger roots and 0.5.
        uvrs = circles_uv_for_pair(vwall, hwall)
        rmax = 0.5
        for (u, v, rc) in uvrs:
            S = u + v + rc
            T = u*u + v*v - rc*rc
            disc = S*S - T
            if disc < 0:
                # no tangency crossing -> does not constrain
                continue
            root = S + np.sqrt(max(0.0, disc))
            if root < rmax:
                rmax = root
                if rmax < 0:
                    return None
        if rmax <= 1e-8:
            return None
        # Candidate center in transformed coords: (rmax, rmax)
        x, y = wall_inverse_pair(vwall, hwall, rmax, rmax)
        if feasible(x, y, rmax):
            return (x, y, rmax)
        return None

    def two_walls_one_circle_candidates(vwall, hwall):
        # For each existing circle j, compute circle tangent to both walls (corner) and to that circle.
        cands = []
        uvrs = circles_uv_for_pair(vwall, hwall)
        for (u, v, rc) in uvrs:
            S = u + v + rc
            T = u*u + v*v - rc*rc
            disc = S*S - T
            if disc < -1e-12:
                continue
            disc = max(0.0, disc)
            roots = [S - np.sqrt(disc), S + np.sqrt(disc)]
            for r in roots:
                if r <= 1e-9 or r > 0.5 + 1e-9:
                    continue
                x, y = wall_inverse_pair(vwall, hwall, r, r)
                if feasible(x, y, r):
                    c = (x, y, r)
                    if not dedup_candidate(cands, c):
                        cands.append(c)
        return cands

    def one_wall_two_circles_candidates(wall):
        # For each pair of circles, compute circle tangent to given wall and to both circles.
        # In (u,v), center is (r, v), with constraints:
        # (ui - r)^2 + (vi - v)^2 = (r + ri)^2 for i=a,b
        # Solve for v as linear function of r (if vi != vj), then quadratic in r.
        cands = []
        uvrs = circles_uv_for_single_wall(wall)
        m = uvrs.shape[0]
        if m < 2:
            return cands
        for a in range(m):
            ua, va, ra = uvrs[a]
            for b in range(a+1, m):
                ub, vb, rb = uvrs[b]
                Dy = va - vb
                Dx = ua - ub
                Dr = ra - rb
                if abs(Dy) > 1e-12:
                    C = ua*ua - ub*ub + va*va - vb*vb - (ra*ra - rb*rb)
                    a_lin = C / (2.0 * Dy)
                    b_lin = (Dx + Dr) / Dy  # v = a_lin - b_lin * r
                    # Quadratic: (b^2) r^2 + 2[ -ua + b(va - a) - ra ] r + [ua^2 + (va - a)^2 - ra^2] = 0
                    Aq = b_lin*b_lin
                    Bq = 2.0 * (-ua + b_lin*(va - a_lin) - ra)
                    Cq = ua*ua + (va - a_lin)*(va - a_lin) - ra*ra
                    roots = []
                    if abs(Aq) < 1e-14:
                        if abs(Bq) > 1e-14:
                            r = -Cq / Bq
                            roots = [r]
                    else:
                        disc = Bq*Bq - 4.0*Aq*Cq
                        if disc >= -1e-12:
                            disc = max(0.0, disc)
                            sqrt_disc = np.sqrt(disc)
                            r1 = (-Bq - sqrt_disc) / (2.0*Aq)
                            r2 = (-Bq + sqrt_disc) / (2.0*Aq)
                            roots = [r1, r2]
                    for r in roots:
                        if r is None:
                            continue
                        if r <= 1e-9 or r > 0.5 + 1e-9:
                            continue
                        v = a_lin - b_lin * r
                        if v < r - 1e-8 or v > 1.0 - r + 1e-8:
                            continue
                        x, y = wall_inverse_single(wall, r, v)
                        if feasible(x, y, r):
                            c = (x, y, r)
                            if not dedup_candidate(cands, c):
                                cands.append(c)
                else:
                    # va == vb; derive r first
                    denom = 2.0 * (Dx + Dr)
                    if abs(denom) < 1e-14:
                        continue
                    r = ((ua*ua - ub*ub) - (ra*ra - rb*rb)) / denom
                    if r <= 1e-9 or r > 0.5 + 1e-9:
                        continue
                    # Solve for v from one circle
                    term = (r + ra)*(r + ra) - (ua - r)*(ua - r)
                    if term < -1e-12:
                        continue
                    term = max(0.0, term)
                    root = np.sqrt(term)
                    for v in (va + root, va - root):
                        if v < r - 1e-8 or v > 1.0 - r + 1e-8:
                            continue
                        x, y = wall_inverse_single(wall, r, v)
                        if feasible(x, y, r):
                            c = (x, y, r)
                            if not dedup_candidate(cands, c):
                                cands.append(c)
        return cands

    # Main greedy insertion loop
    # Stop when we place 26 circles or time runs out or we cannot add any more.
    iter_limit = 2000
    it = 0
    while len(radii) < max_circles and it < iter_limit and (time.time() - start_time) < time_limit:
        it += 1
        candidates = []

        # 1) Corner-only maximal circle candidates at four corners
        for vwall in (0, 1):
            for hwall in (2, 3):
                cand = corner_only_candidate(vwall, hwall)
                if cand is not None and not dedup_candidate(candidates, cand):
                    candidates.append(cand)

        # 2) Two walls + one circle (for each existing circle, at each corner)
        for vwall in (0, 1):
            for hwall in (2, 3):
                cands2 = two_walls_one_circle_candidates(vwall, hwall)
                for c in cands2:
                    if not dedup_candidate(candidates, c):
                        candidates.append(c)

        # 3) One wall + two circles (for each wall)
        for wall in (0, 1, 2, 3):
            cands3 = one_wall_two_circles_candidates(wall)
            for c in cands3:
                if not dedup_candidate(candidates, c):
                    candidates.append(c)

        if not candidates:
            # If no candidates, try to loosen feasibility slightly: attempt very small circles at corners
            tiny = 1e-3
            fallback = False
            for vwall in (0, 1):
                for hwall in (2, 3):
                    x, y = wall_inverse_pair(vwall, hwall, tiny, tiny)
                    if feasible(x, y, tiny):
                        add_circle(x, y, tiny)
                        fallback = True
                        if len(radii) >= max_circles:
                            break
                if fallback and len(radii) >= max_circles:
                    break
            if not fallback:
                break
            else:
                continue

        # Select the largest-radius candidate
        candidates.sort(key=lambda t: t[2], reverse=True)
        placed = False
        for (x, y, r) in candidates:
            # Avoid adding a circle that's essentially already present
            dup = False
            for (cx, cy), cr in zip(centers, radii):
                if abs(cr - r) < 1e-8 and np.hypot(cx - x, cy - y) < 1e-8:
                    dup = True
                    break
            if dup:
                continue
            if feasible(x, y, r):
                add_circle(x, y, r)
                placed = True
                break
        if not placed:
            # If cannot place any, slightly reduce tolerance by trimming candidates and retry next iter
            # Or try adding tiny circle at the best corner
            tiny = 1e-3
            tried = False
            for vwall in (0, 1):
                for hwall in (2, 3):
                    x, y = wall_inverse_pair(vwall, hwall, tiny, tiny)
                    if feasible(x, y, tiny):
                        add_circle(x, y, tiny)
                        tried = True
                        break
                if tried:
                    break
            if not tried:
                break

    # If less than 26, try sprinkling tiny circles in remaining gaps near corners/edges
    tries = 0
    while len(radii) < max_circles and tries < 200 and (time.time() - start_time) < time_limit:
        tries += 1
        # Try corners first
        placed = False
        for vwall in (0, 1):
            for hwall in (2, 3):
                # Find smallest feasible r at that corner by shrinking
                r = 5e-3
                for _ in range(5):
                    x, y = wall_inverse_pair(vwall, hwall, r, r)
                    if feasible(x, y, r):
                        add_circle(x, y, r)
                        placed = True
                        break
                    r *= 0.5
                if placed:
                    break
            if placed:
                break
        if not placed:
            # Random small attempt near edges
            wall = np.random.choice([0,1,2,3])
            r = 5e-3
            t = np.random.rand()
            if wall in (0,1):
                # vertical wall: u=r, v in [r, 1-r]
                v = r + t*(1 - 2*r)
                x, y = wall_inverse_single(wall, r, v)
            else:
                # horizontal wall
                v = r + t*(1 - 2*r)
                x, y = wall_inverse_single(wall, r, v)
            if feasible(x, y, r):
                add_circle(x, y, r)

    centers_arr = np.array(centers, dtype=float)
    radii_arr = np.array(radii, dtype=float)
    # If more than 26 due to fallback, trim smallest
    if len(radii_arr) > max_circles:
        idx = np.argsort(-radii_arr)[:max_circles]
        centers_arr = centers_arr[idx]
        radii_arr = radii_arr[idx]
    # If less than 26, pad with zeros (feasible but degenerate)
    if len(radii_arr) < max_circles:
        need = max_circles - len(radii_arr)
        if len(radii_arr) == 0:
            pad_centers = np.zeros((need,2))
        else:
            pad_centers = np.tile(centers_arr[-1], (need,1))
        centers_arr = np.vstack([centers_arr, pad_centers[:need]])
        radii_arr = np.concatenate([radii_arr, np.zeros(need)])
    sum_radii = float(np.sum(radii_arr))
    return centers_arr, radii_arr, sum_radii

if __name__ == "__main__":
    c, r, s = run_packing()
    print("centers:", c)
    print("radii:", r)
    print("sum_radii:", s)
